import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.BmD0ICqc.js";const u=JSON.parse('{"title":"斜めの床でテクスチャのフィルタリングを比べる","description":"","frontmatter":{"title":"斜めの床でテクスチャのフィルタリングを比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"texture-filtering-observation","order":1,"summary":"WebGL 2で同じ床を描き、ポイント、バイリニア、トライリニア、異方性を切り替えて遠くの模様を観察する。","aliases":["テクスチャの実践","WebGL 2","ポイント","バイリニア","トライリニア","ミップマップ","異方性","ちらつき"],"verification":"KhronosのWebGL 2.0と異方性フィルタリング拡張仕様に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/texture-filtering-observation.md","filePath":"practice/graphics/texture-filtering-observation.md"}'),o={name:"practice/graphics/texture-filtering-observation.md"};function s(l,e,n,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="斜めの床でテクスチャのフィルタリングを比べる" tabindex="-1">斜めの床でテクスチャのフィルタリングを比べる <a class="header-anchor" href="#斜めの床でテクスチャのフィルタリングを比べる" aria-label="Permalink to &quot;斜めの床でテクスチャのフィルタリングを比べる&quot;">​</a></h1><p><a href="/study/graphics/texture/texture-filtering-and-mipmaps.html">テクスチャのフィルタリングとミップマップ</a>で説明した4種類の方法を、同じ床で比べます。手前の模様、奥の模様、カメラを動かしたときの変化を順に見ます。</p><p><a href="/study/samples/graphics/texture-filtering-observation/index.html" target="_self">床のフィルタリング比較を開く</a></p><h2 id="同じ位置で見比べる" tabindex="-1">同じ位置で見比べる <a class="header-anchor" href="#同じ位置で見比べる" aria-label="Permalink to &quot;同じ位置で見比べる&quot;">​</a></h2><ol><li>初期状態の<strong>ポイント</strong>で、手前の模様の境目と、遠くに見える模様を覚えておきます。</li><li>カメラを停止したまま<strong>バイリニア</strong>に切り替えます。手前で境目がどう変わり、奥にどんな模様が残るかを見ます。</li><li>**トライリニア（ミップマップ）**に切り替え、床の奥で細かい模様がならされる様子を確認します。</li><li><strong>異方性</strong>を選べる場合は、床の奥へ伸びる細い縞に注目します。横に並んだ縞をどこまで見分けられるか、トライリニアと比べます。</li></ol><h2 id="カメラを動かして、ちらつきを見る" tabindex="-1">カメラを動かして、ちらつきを見る <a class="header-anchor" href="#カメラを動かして、ちらつきを見る" aria-label="Permalink to &quot;カメラを動かして、ちらつきを見る&quot;">​</a></h2><p><strong>カメラを横に動かす</strong>をオンにして、遠くの同じ範囲に目を向けます。ポイントとバイリニアでは、静止時に見えていた模様が動いたり、明滅したりする場合があります。トライリニアに切り替えると、模様の細かい変化がどの程度減るか比べられます。</p><p>カメラを再び停止すると初期位置に戻るので、同じ位置から比較できます。床の形、UV、テクスチャは共通です。表示の違いは画面の解像度やGPU・ブラウザーの実装にもよるので、奥の模様が変化する場所を目印にします。</p><h2 id="webglで変えている設定" tabindex="-1">WebGLで変えている設定 <a class="header-anchor" href="#webglで変えている設定" aria-label="Permalink to &quot;WebGLで変えている設定&quot;">​</a></h2><p>縮小時の設定を変えるのは <code>TEXTURE_MIN_FILTER</code> です。<code>generateMipmap</code> で用意した縮小画像は、トライリニアと異方性で使います。異方性モードではトライリニアの設定を使い、<code>TEXTURE_MAX_ANISOTROPY_EXT</code> に実装の上限と8の小さい方を設定します。拡張が使えないか上限が1以下の場合、画面に理由が表示され、残り3種類を試せます。WebGL 2を使えない場合も、起動時に状態を表示します。</p><table tabindex="0"><thead><tr><th>観察</th><th>対応する設定</th></tr></thead><tbody><tr><td>元画像から1テクセルを選ぶ</td><td><code>NEAREST</code></td></tr><tr><td>元画像の周囲を混ぜる</td><td><code>LINEAR</code></td></tr><tr><td>複数の解像度を使って混ぜる</td><td><code>LINEAR_MIPMAP_LINEAR</code></td></tr><tr><td>細長い範囲に合わせる</td><td><code>EXT_texture_filter_anisotropic</code></td></tr></tbody></table><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>カメラを止めて見比べると、何をそろえた状態でフィルターを比べられますか。</p><details class="details custom-block"><summary>解答</summary><p>床の形、テクスチャ、カメラの位置がそろいます。同じ画面上の位置で、設定を変えたときの見え方を比較できます。</p></details></li><li><p>奥の床で、ポイントよりトライリニアの方が安定して見えました。何が変わりましたか。</p><details class="details custom-block"><summary>解答</summary><p>トライリニアは縮小した画像を使い、1画素が覆う広い範囲の色を反映します。元画像の一点を選んだときに生じる急な色の切り替わりが抑えられます。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/texture/texture-filtering-and-mipmaps.html">テクスチャのフィルタリングとミップマップ</a>で、1画素が覆う範囲とLODを確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-pipeline#graphics">3DCG・描画ロードマップの「レンダリングパイプライン」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://registry.khronos.org/webgl/specs/latest/2.0/" target="_blank" rel="noreferrer">Khronos — WebGL 2.0 Specification</a> · <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">OpenGL ES 3.0.6 Specification</a> · <a href="https://registry.khronos.org/webgl/extensions/EXT_texture_filter_anisotropic/" target="_blank" rel="noreferrer">WebGL EXT_texture_filter_anisotropic</a></li></ul>',17)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
